// ─── Element Types ───────────────────────────────────────────────────────────

/**
 * A standard table column field element.
 *
 * @template T - The table name type.
 */
type TableFieldElement<T extends TableName> = {
    /** Column name from the table schema (e.g., `'name'`, `'active'`, `'description'`). */
    readonly field: TableSchemaDotWalk<T>
    /** Must be `'table_field'`. */
    readonly type: 'table_field'
}

/**
 * An annotation element that displays informational text on the form.
 */
type AnnotationElement = {
    /** Must be `'annotation'`. */
    readonly type: 'annotation'
    /** Reference to a `sys_ui_annotation` record ID (e.g., `Now.ID['form_notice']`). */
    readonly annotationId: Now.Internal.ExplicitKey
    /** Annotation text content displayed on the form. */
    readonly text: string
    /** Whether `text` is plain text (`true`) or contains HTML (`false`). Defaults to `true`. */
    readonly isPlainText?: boolean
    /** Annotation styling type. Use a predefined key (e.g., `'Info_Box_Blue'`) or a `sys_ui_annotation_type` sys_id string. */
    readonly annotationType?: keyof typeof AnnotationType | Record<'sys_ui_annotation_type'> | (string & {})
}

/**
 * A formatter element that displays special UI components (e.g., activity streams).
 */
type FormatterElement = {
    /** Must be `'formatter'`. */
    readonly type: 'formatter'
    /** Formatter name (e.g., `'activity.xml'`). Optional — automatically derived from `formatterRef` for predefined `Formatter.*` keys. Provide explicitly for custom formatters or to retain the value during round-trip transforms. */
    readonly formatterName?: string
    /** Formatter key (e.g., `'Activities_Filtered'`), `sys_id` (GUID), or a `Record<'sys_ui_formatter'>` reference. */
    readonly formatterRef: keyof typeof Formatter | Record<'sys_ui_formatter'> | (string & {})
}

/**
 * An implicit (12M or M2M) related list element.
 * 12M shows child records that reference the form's table via a reference column.
 * M2M shows related records via a join/intermediary table.
 */
type ImplicitListElement = {
    /** Must be `'list'`. */
    readonly type: 'list'
    /** `'12M'` for one-to-many or `'M2M'` for many-to-many. */
    readonly listType: '12M' | 'M2M'
    /** Dot-notation reference: `'<table_name>.<column_name>'` (e.g., `'task_sla.task'` for 12M, `'m2m_task_project.task_ref'` for M2M). */
    readonly listRef: string
}

/**
 * A custom relationship related list element.
 * Uses a `sys_relationship` record to define an arbitrary relationship.
 */
type CustomListElement = {
    /** Must be `'list'`. */
    readonly type: 'list'
    /** Must be `'custom'`. */
    readonly listType: 'custom'
    /** Reference to a `sys_relationship` record or a `sys_relationship` sys_id string (GUID). */
    readonly listRef: Record<'sys_relationship'> | string
}

/**
 * Union of all related list element types.
 */
type ListElement = ImplicitListElement | CustomListElement

/**
 * Union of all form element types that can appear in a layout block.
 *
 * @template T - The table name type.
 */
type FormElement<T extends TableName> = TableFieldElement<T> | AnnotationElement | FormatterElement | ListElement

// ─── Layout Blocks ───────────────────────────────────────────────────────────

/**
 * A one-column layout block. All elements are stacked vertically.
 *
 * @template T - The table name type.
 */
type OneColumnLayout<T extends TableName> = {
    /** Must be `'one-column'`. */
    readonly layout: 'one-column'
    /** Array of elements displayed in a single column. */
    readonly elements: Array<FormElement<T>>
}

/**
 * A two-column layout block. Elements are split into left and right columns.
 * Maps to `.begin_split` / `.split` / `.end_split` element records in ServiceNow.
 *
 * @template T - The table name type.
 */
type TwoColumnLayout<T extends TableName> = {
    /** Must be `'two-column'`. */
    readonly layout: 'two-column'
    /** Array of elements displayed in the left column. */
    readonly leftElements: Array<FormElement<T>>
    /** Array of elements displayed in the right column. */
    readonly rightElements: Array<FormElement<T>>
}

/**
 * A layout block defines the column arrangement for a group of elements within a section.
 * Each section can contain multiple layout blocks, enabling mixed layouts
 * (e.g., a one-column block followed by a two-column block).
 *
 * @template T - The table name type.
 */
type LayoutBlock<T extends TableName> = OneColumnLayout<T> | TwoColumnLayout<T>

// ─── Section & Form ──────────────────────────────────────────────────────────

/**
 * Represents a section within a form containing layout blocks.
 *
 * @template T - The table name type.
 */
type FormSection<T extends TableName> = {
    /** Section header text. Must be non-empty. */
    readonly caption: string
    /** Whether this section should be rendered as a header. */
    readonly header?: boolean
    /** Display title for the section. Maps to the `title` field on `sys_ui_section` (max 40 chars). When set, the section is rendered as a title/header row on the form. */
    readonly title?: boolean
    /** Array of layout blocks defining the column structure and elements for this section. A section can contain multiple layout blocks to create mixed one-column and two-column arrangements (equivalent to the "merge section" feature in ServiceNow Form Designer). */
    readonly content: Array<LayoutBlock<T>>
}

/** @interface */
type Form<T extends TableName = TableName> = Now.Internal.WithMetadata<{
    /** The ServiceNow table this form is associated with. Must have scope prefix for scoped apps (e.g., `sn_my_app_`). */
    table: T
    /** View name string or reference to a `sys_ui_view` record. Use `default_view` for the default view. */
    view: string | Record<'sys_ui_view'>
    /** Personalize the form for a specific user. Can be a string username or a reference to a `sys_user` record. */
    user?: string | Record<'sys_user'>
    /** Array of role names or Role objects that have access to this form. */
    roles?: (string | Role)[]
    /** Array of form sections containing layout blocks. At least one section is required. */
    sections: Array<FormSection<T>>
}>

/**
 * Creates a form definition (`sys_ui_form`) for a ServiceNow table with sections and layout blocks.
 *
 * The Form API creates the following ServiceNow records:
 * - `sys_ui_form` — Main form record linking table and view
 * - `sys_ui_form_section` — Join table linking form to sections
 * - `sys_ui_section` — Section records with caption and layout
 * - `sys_ui_element` — Individual field elements within sections
 * - `sys_ui_annotation` — Annotation records (when `type: 'annotation'`)
 *
 */

export function Form<const T extends TableName>(config: Form<T>) {
    return config
}
